  id String @id @db.Uuid

  /// Belonged user's {@link discussion_board_users.id}.
  discussion_board_user_id String @db.Uuid

  /// IP address of the connection that created this session for security
  /// tracking.
  ip String

  /// Connection URL where the session was initiated for contextual logging.
  href String

  /// Referrer URL that brought the user to the session creation endpoint.
  referrer String

  /// Session creation timestamp when the user successfully authenticated.
  created_at DateTime @db.Timestamptz

  /// Session expiration timestamp when the session becomes invalid - sessions
  /// must expire for security.
  expired_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  user discussion_board_users @relation(fields: [discussion_board_user_id], references: [id], onDelete: Cascade)

