  discussion_board_ban_id String @db.Uuid

  /// The administrator who performed this action. {@link
  /// discussion_board_administrators.id}
  discussion_board_administrator_id String @db.Uuid

  /// Type of administrative action performed on the ban record. Valid values:
  /// 'application', 'modification', 'extension', 'removal'.
  action_type String

  /// Additional context or notes about the administrative action, providing
  /// details about the decision or circumstances.
  action_context String?

  /// Timestamp when the administrative action was recorded.
  created_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  ban           discussion_board_bans           @relation(fields: [discussion_board_ban_id], references: [id], onDelete: Cascade)
  // spellchecker: ignore-next-line
  administrator discussion_board_administrators @relation(fields: [discussion_board_administrator_id], references: [id], onDelete: Cascade, map: "discussion_board_ban_admin_actions_discussion_board_ad_58558fde")

  // spellchecker: ignore-next-line
  @@index([discussion_board_ban_id, created_at], map: "discussion_board_ban_admin_actions_discussion_board_ba_f8854739")
  // spellchecker: ignore-next-line
  @@index([discussion_board_administrator_id, created_at], map: "discussion_board_ban_admin_actions_discussion_board_ad_5be8e8a7")
}

